function slide(heading, text, visualIcon, actions, popup, relatedLinks) {
  return { heading, text, visualIcon, actions, popup, relatedLinks };
}

function popup(label, key, icon, accent) {
  return { label, popup: key || "default", icon, accent: Boolean(accent) };
}

function link(label, presentation, icon, slideNumber) {
  return { label, presentation, icon, slide: slideNumber ? slideNumber + 1 : 1 };
}

function href(label, url, icon, accent) {
  return { label, href: url, icon, accent: Boolean(accent), external: /^https?:/.test(url) };
}

function homeView(label, view, icon, accent) {
  return { label, homeView: view, icon, accent: Boolean(accent) };
}

function related(label, presentation, slideNumber) {
  return { label, presentation, slide: slideNumber ? slideNumber + 1 : 1 };
}

